<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { api } from '../api/client'
import type { ComponentDescriptor, ComposerStage, ProfileComposerCatalog, ProfileComposerPreflightResponse } from '../api/contracts'
import { useProfileDraft } from '../composables/useProfileDraft'
const { draft, updateStage, toggleChecker } = useProfileDraft()
const catalog = ref<ProfileComposerCatalog | null>(null), result = ref<ProfileComposerPreflightResponse | null>(null), error = ref(''), loading = ref(true), checking = ref(false), dragging = ref<{ stage: ComposerStage; id: string } | null>(null)
const lanes: Array<{ id: ComposerStage; label: string; hint: string }> = [{ id: 'source', label: '1. Source', hint: '需求来源' }, { id: 'compiler', label: '2. Compiler', hint: '生成 Spec' }, { id: 'maker', label: '3. Maker', hint: '生成代码' }, { id: 'checker', label: '4. Checkers', hint: '可多个、可排序' }, { id: 'delivery', label: '5. Delivery', hint: '交付去向' }]
const stage = (name: ComposerStage): ComponentDescriptor[] => catalog.value?.stages[name] || []
const descriptor = (name: ComposerStage, id: string) => stage(name).find(item => item.id === id)
const inLane = (name: ComposerStage) => name === 'source' ? [descriptor(name, draft.source.name)] : name === 'compiler' ? [descriptor(name, draft.compiler)] : name === 'maker' ? [descriptor(name, draft.maker)] : name === 'delivery' ? [descriptor(name, draft.delivery)] : draft.checkers.map(id => descriptor(name, id)).filter(Boolean)
const capability = (item?: ComponentDescriptor) => item ? Object.entries(item.capabilities).filter(([, enabled]) => enabled).map(([name]) => name).join(' · ') || '离线本地' : '未选择'
function begin(stageName: ComposerStage, id: string, event: DragEvent) { dragging.value = { stage: stageName, id }; event.dataTransfer?.setData('text/plain', `${stageName}:${id}`); if (event.dataTransfer) event.dataTransfer.effectAllowed = 'copy' }
function drop(stageName: ComposerStage, event: DragEvent) { event.preventDefault(); const value = dragging.value || (() => { const [stageNameFromData, id] = (event.dataTransfer?.getData('text/plain') || ':').split(':'); return { stage: stageNameFromData as ComposerStage, id } })(); dragging.value = null; if (value.stage !== stageName) { error.value = '固定链路只接受拖入所属泳道的节点，不能跳过或重排阶段。'; return } error.value = ''; if (stageName === 'checker') { if (!draft.checkers.includes(value.id)) toggleChecker(value.id) } else updateStage(stageName, value.id) }
async function preflight() { checking.value = true; error.value = ''; try { result.value = await api.preflightProfileDraft(draft); if (!result.value.valid) error.value = '预检发现需要修复的组合或权限问题。' } catch (e) { error.value = e instanceof Error ? e.message : 'Profile 预检失败' } finally { checking.value = false } }
watch(draft, () => { result.value = null }, { deep: true })
onMounted(async () => { try { catalog.value = (await api.profileComposerCatalog()).catalog } catch (e) { error.value = e instanceof Error ? e.message : '无法读取组件目录' } finally { loading.value = false } })
</script>
<template><section class="page composer-canvas"><div class="page-heading"><div><p class="eyebrow">ALLOWLIST PALETTE → FIXED PROFILE GRAPH</p><h1>Profile 画布编排</h1><p>从左侧组件区拖入相应泳道；画布与下拉页共用同一个 Draft。它不是任意工作流编辑器，阶段顺序固定且由服务端预检。</p></div><div><RouterLink class="quiet-button" to="/profile-composer/form">切换到下拉编排</RouterLink><RouterLink class="quiet-button" to="/profile-composer/save">保存 Profile</RouterLink></div></div><p v-if="error" class="data-warning">⚠ {{ error }}</p><p v-if="loading" class="empty-state">正在读取服务端组件目录…</p><template v-else-if="catalog"><section class="canvas-layout"><aside class="workspace-panel palette"><h2>组件区</h2><p>只显示服务端许可节点；不含真实配置或密钥。</p><section v-for="lane in lanes" :key="lane.id"><b>{{ lane.label }}</b><button v-for="item in stage(lane.id)" :key="item.id" draggable="true" @dragstart="begin(lane.id, item.id, $event)" @click="lane.id === 'checker' ? toggleChecker(item.id) : updateStage(lane.id as Exclude<ComposerStage, 'checker'>, item.id)"><strong>{{ item.label }}</strong><small>{{ capability(item) }}</small></button></section></aside><main class="workspace-panel flow-canvas"><header><div><h2>完整 Profile 链路</h2><span>拖动节点到同名泳道；Checker 可叠加</span></div><button class="primary-button" :disabled="checking" @click="preflight">{{ checking ? '正在预检…' : '预检草稿' }}</button></header><section class="lanes"><article v-for="lane in lanes" :key="lane.id" class="lane" :class="{ over: dragging?.stage === lane.id }" @dragover.prevent @drop="drop(lane.id, $event)"><header><b>{{ lane.label }}</b><small>{{ lane.hint }}</small></header><div class="drop-zone"><button v-for="item in inLane(lane.id)" :key="item?.id" class="node" @click="lane.id === 'checker' && item && toggleChecker(item.id)"><span>{{ item?.label || '请选择节点' }}</span><small>{{ capability(item) }}{{ item?.experimental ? ' · 实验性' : '' }}</small></button><span v-if="!inLane(lane.id).length" class="lane-empty">拖入 {{ lane.label }} 节点</span></div></article></section></main><aside class="workspace-panel properties"><h2>草稿属性</h2><label>Profile ID<input v-model="draft.id" /></label><label>版本<input v-model.number="draft.version" type="number" min="1" /></label><label>说明<textarea v-model="draft.description" rows="4" /></label><h3>权限</h3><label class="permission"><input v-model="draft.policy.allow_network" type="checkbox" />网络</label><label class="permission"><input v-model="draft.policy.allow_model" type="checkbox" />模型</label><label class="permission"><input v-model="draft.policy.allow_git" type="checkbox" />Git</label><label class="permission"><input v-model="draft.policy.allow_ssh" type="checkbox" />SSH</label><label class="permission"><input v-model="draft.policy.allow_publish" type="checkbox" />发布</label><label class="permission"><input v-model="draft.policy.allow_deploy" type="checkbox" />部署</label><p class="policy-note">画布不保存也不执行。预检通过后可前往“保存 Profile”注册；实际外部执行仍由新建需求页的“确认并执行”触发，浏览器不接触凭据。</p></aside></section><section v-if="result" class="workspace-panel canvas-result"><div><h2>{{ result.valid ? '预检通过' : '预检未通过' }}</h2><p>执行 {{ result.execution.performed ? '是' : '否' }} · 写入 {{ result.execution.writes ? '是' : '否' }} · 网络 {{ result.execution.network ? '是' : '否' }}</p></div><ul class="diagnostics"><li v-for="item in result.diagnostics" :key="`${item.path}-${item.code}`" :class="item.severity"><code>{{ item.path }}</code> {{ item.message }}</li><li v-if="!result.diagnostics.length" class="saved">✓ 服务端纯规则校验通过。</li></ul><pre>{{ JSON.stringify(result.normalized_profile || draft, null, 2) }}</pre></section></template></section></template>
<style scoped>.canvas-layout{display:grid;grid-template-columns:250px minmax(420px,1fr) 245px;gap:12px}.palette h2,.properties h2,.flow-canvas h2{margin:0;font-size:14px}.palette>p,.policy-note,.flow-canvas header span{color:var(--soft);font-size:10px}.palette section{margin-top:15px}.palette section>b{display:block;margin-bottom:6px;color:var(--violet);font-size:10px}.palette button{display:block;width:100%;margin:5px 0;padding:8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-2);color:var(--ink);text-align:left;cursor:grab}.palette strong,.palette small{display:block}.palette small{color:var(--soft);font-size:9px}.flow-canvas>header{display:flex;justify-content:space-between;gap:12px}.lanes{display:grid;gap:8px;margin-top:16px}.lane{display:grid;grid-template-columns:115px 1fr;min-height:76px;border:1px dashed var(--line);border-radius:10px;overflow:hidden}.lane.over{border-color:var(--blue);background:color-mix(in srgb,var(--blue) 8%,transparent)}.lane>header{padding:12px;border-right:1px solid var(--line-soft);background:color-mix(in srgb,var(--ink) 3%,transparent)}.lane b,.lane small{display:block}.lane small{color:var(--soft);font-size:9px}.drop-zone{display:flex;align-items:center;gap:8px;padding:9px;flex-wrap:wrap}.node{border:1px solid color-mix(in srgb,var(--blue) 45%,var(--line));border-radius:8px;background:color-mix(in srgb,var(--blue) 10%,var(--panel));padding:7px 9px;color:var(--ink);text-align:left;cursor:pointer}.node span,.node small{display:block}.node small{margin-top:2px;color:var(--soft);font-size:9px}.lane-empty{color:var(--soft);font-size:11px}.properties label{display:grid;gap:5px;margin:10px 0;color:var(--muted);font-size:11px}.properties input,.properties textarea{width:100%;border:1px solid var(--line);border-radius:7px;background:var(--panel-2);padding:8px;color:var(--ink);font:inherit}.properties h3{margin:19px 0 8px;font-size:12px}.properties .permission{display:flex;align-items:center;gap:6px;margin:7px 0}.properties .permission input{width:auto}.canvas-result{display:grid;grid-template-columns:.7fr 1fr 1.2fr;gap:18px;margin-top:14px}.canvas-result p{color:var(--soft);font-size:11px}.diagnostics{margin:0;padding-left:17px;font-size:11px}.diagnostics .error{color:var(--red)}.diagnostics .warning{color:var(--amber)}pre{max-height:290px;overflow:auto;margin:0;padding:10px;border-radius:8px;background:var(--panel-2);font-size:10px}@media(max-width:1050px){.canvas-layout{grid-template-columns:220px 1fr}.properties{grid-column:1/-1}.canvas-result{grid-template-columns:1fr}}@media(max-width:690px){.canvas-layout{grid-template-columns:1fr}.lane{grid-template-columns:1fr}.lane>header{border-right:0;border-bottom:1px solid var(--line-soft)}.flow-canvas>header{display:block}.palette{order:2}.properties{order:3}}</style>
